// CẤU HÌNH THÔNG TIN CÁC KÊNH KOCITY CỦA BẠN TẠI ĐÂY
// Sau khi gắn API/Scraper ở các node sau, dữ liệu thật sẽ tự động đổ vào Supabase bảng kocity_channel_metrics
const today = new Date().toISOString().split('T')[0];

return [
  {
    json: {
      report_date: today,
      supabase_url: 'https://mjsmnkelreniasahhfkf.supabase.co',
      channels: {
        website: { url: 'https://kocity.io.vn', name: 'Website KOCity' },
        tiktok: { handle: 'kocity.vn', url: 'https://www.tiktok.com/@kocity.vn', name: 'TikTok KOCity' },
        facebook: { pageId: 'YOUR_FB_PAGE_ID', url: 'https://facebook.com/groups/kocityvietnam', name: 'Facebook KOCity' },
        threads: { handle: 'kocity.vn', url: 'https://www.threads.net/@kocity.vn', name: 'Threads KOCity' },
        zalo: { url: 'https://zalo.me/g/cjenmz664', name: 'Zalo Community' }
      }
    }
  }
];

// Tổng hợp dữ liệu thật từ các nguồn (Website Supabase + TikTok/FB/Threads/Zalo API)
// Bạn có thể nối thêm node Facebook Graph API, Threads API, Apify TikTok vào trước node này
const today = new Date().toISOString().split('T')[0];
const webApps = $input.all().map(i => i.json);
const totalApps = webApps.length;
const todayApps = webApps.filter(a => (a.created_at || '').startsWith(today)).length;

const rows = [
  {
    report_date: today,
    channel: 'website',
    channel_name: 'Website KOCity',
    channel_url: 'https://kocity.io.vn',
    followers_or_members: totalApps,
    total_views: totalApps * 45,
    engagements: totalApps,
    new_subscribers_today: todayApps,
    notes: `Đồng bộ tự động lúc ${new Date().toLocaleTimeString('vi-VN')} (${totalApps} hồ sơ thật)`
  }
];

return rows.map(r => ({ json: r }));
